<template>
 <div class="v2-stack">
  <section class="v2-dashboard-hero"><div><span class="v2-eyebrow">IL PROSSIMO PASSO, SEMPRE CHIARO</span><h2>{{ c.activeEventEntry ? 'La tua arena è in gioco.' : 'Prepariamo la prossima partita.' }}</h2><p>{{ c.activeEventEntry ? 'Gestisci l’esperienza attiva e segui le operazioni della tua società.' : 'Crea un evento, prepara il roster e dai ai tuoi fan un’esperienza da ricordare.' }}</p><button class="v2-button" @click="c.navigate('events',c.activeEventEntry ? String(c.activeEventEntry.id) : 'create')">{{ c.activeEventEntry ? 'Gestisci evento attivo' : 'Crea il tuo evento' }}<V2Icon name="arrow-right" :size="17" /></button></div><div class="v2-hero-symbol" aria-hidden="true"><V2Icon name="boost" :size="94" /></div><span class="v2-hero-caption">IL TUO CLUB. LA TUA ARENA.</span></section>
  <div class="v2-grid-4"><article v-for="metric in metrics" :key="metric.label" class="v2-metric"><div class="v2-metric-top"><span>{{ metric.label }}</span><V2Icon :name="metric.icon" :size="18" /></div><strong>{{ metric.value }}</strong><small>{{ metric.hint }}</small></article></div>
  <div class="v2-dashboard-columns"><V2Panel title="In programma" description="Gli eventi operativi della società."><template #actions><button class="v2-link" @click="c.navigate('events')">Tutti gli eventi <span aria-hidden="true">↗</span></button></template><div v-if="!upcoming.length" class="v2-empty"><V2Icon name="events" :size="30" /><p>Nessun evento in programma.</p><button class="v2-button" @click="c.navigate('events','create')">Crea un evento</button></div><div v-else class="v2-event-list"><button v-for="event in upcoming" :key="event.id" class="v2-event-row" @click="c.navigate('events',String(event.id))"><span class="v2-event-date"><strong>{{ datePart(event,'day') }}</strong><small>{{ datePart(event,'month') }}</small></span><span class="v2-event-row-content"><strong>{{ c.eventLabel(event) }}</strong><small>{{ c.formatEventDate(event.start_datetime) }}<template v-if="event.location"> · {{ event.location }}</template></small></span><span class="v2-badge" :class="event.is_active ? 'success' : ''">{{ event.is_active ? event.votes_closed ? 'Voti chiusi' : 'Attivo' : 'Inattivo' }}</span><V2Icon name="chevron-right" :size="17" /></button></div></V2Panel>
   <V2Panel title="Azioni frequenti" description="Le operazioni che ti servono ogni giorno."><div class="v2-shortcuts"><button v-for="item in shortcuts" :key="item.id" @click="c.navigate(item.id)"><span><V2Icon :name="item.id" :size="19" /></span><div><strong>{{ item.label }}</strong><small>{{ item.hint }}</small></div><V2Icon name="chevron-right" :size="16" /></button></div></V2Panel>
  </div>
  <div class="v2-grid-2"><V2Panel title="Stato della società"><div class="v2-status-list"><div v-for="status in statuses" :key="status.label"><span>{{ status.label }}</span><span class="v2-badge" :class="status.ok ? 'success' : 'warning'"><V2Icon v-if="status.ok" name="check" :size="12" />{{ status.text }}</span></div></div></V2Panel><V2Panel title="Votazioni e notifiche" description="Organizzatori, assegnazione premi e biglietti dei tifosi."><div class="v2-settings-teaser"><span class="v2-teaser-icon"><V2Icon name="settings" :size="26" /></span><div><p>Prepara la chiusura della partita.</p><small>Configura i destinatari WhatsApp e verifica il template prima dell’evento.</small></div></div><button class="v2-button" @click="c.navigate('settings')">Apri configurazione<V2Icon name="arrow-right" :size="16" /></button></V2Panel></div>
 </div>
</template>
<script setup>
import { computed, inject } from 'vue';
import V2Panel from '../components/shared/V2Panel.vue';
import V2Icon from '../components/shared/V2Icon.vue';
const c=inject('admin-v2');
const metrics=computed(()=>[
 {label:'Eventi operativi',value:c.availableEvents.length,hint:'Eventi non conclusi',icon:'events'},
 {label:'Giocatori nel roster',value:c.players.length,hint:`${c.players.filter(p=>p.is_called_up).length} convocati`,icon:'players'},
 {label:'Sponsor visibili',value:c.activeSponsorCount,hint:`${c.sponsors.length} sponsor configurati`,icon:'sponsors'},
 {label:'Squadre',value:c.teams.length,hint:'Disponibili per gli eventi',icon:'teams'},
]);
const upcoming=computed(()=>[...c.availableEvents].sort((a,b)=>Number(Boolean(b.is_active))-Number(Boolean(a.is_active))||new Date(a.start_datetime)-new Date(b.start_datetime)).slice(0,5));
const shortcuts=[{id:'players',label:'Aggiorna il roster',hint:'Giocatori e convocazioni'},{id:'closing',label:'Gestisci le votazioni',hint:'Chiusura, premi e notifiche'},{id:'sponsors',label:'Organizza gli sponsor',hint:'Loghi e pubblicazione'},{id:'history',label:'Consulta i report',hint:'Risultati e analisi eventi'}];
const statuses=computed(()=>[{label:'Squadre per creare un evento',ok:c.hasEnoughTeams,text:c.hasEnoughTeams?'Pronte':'Aggiungi almeno 2 squadre'},{label:'Evento attivo',ok:!!c.activeEventEntry,text:c.activeEventEntry?'Configurato':'Nessun evento attivo'},{label:'Roster giocatori',ok:c.players.length>0,text:c.players.length?'Configurato':'Da configurare'},{label:'Sponsor',ok:c.sponsors.length>0,text:c.sponsors.length?'Configurati':'Da configurare'}]);
function datePart(event,part){const date=new Date(event.start_datetime);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat('it-IT',part==='day'?{day:'2-digit'}:{month:'short'}).format(date);}
</script>
