@media(max-width:1250px){.v2-dashboard-columns{grid-template-columns:minmax(0,1fr)}.v2-shortcuts{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.v2-hero-symbol{padding-right:0}}@media(max-width:640px){.v2-dashboard-hero{padding:24px;min-height:230px}.v2-dashboard-hero h2{font-size:24px}.v2-hero-symbol,.v2-hero-caption{display:none}.v2-shortcuts{grid-template-columns:1fr}.v2-event-row{gap:10px}.v2-event-row>.v2-badge{display:none}.v2-status-list>div{align-items:center}.v2-status-list>div>span:first-child{max-width:53%}}
